attempts.query:
PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
SELECT (COUNT(DISTINCT ?t) AS ?n) WHERE {
  ?t oncologia:testsDrug ?d . ?d oncologia:name "PEMBROLIZUMAB" .
  ?t oncologia:status ?st . FILTER(?st IN ("RECRUITING","ACTIVE_NOT_RECRUITING","NOT_YET_RECRUITING","ENROLLING_BY_INVITATION"))
}
